actions.script:
const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.find#InviteLinks').parameter('chatRoomId', chatRoomId || '').call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {linkList: out.linkList || [], canMake: !!out.canMake,
    roomKind: out.roomKind || null, canList: !!out.canList, listed: !!out.listed})

const number = (value) => value == null || value === '' ? null : Number(value)
const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.create#InviteLink').parameters({chatRoomId: chatRoomId || '', label: label || null,
    expiryHours: number(expiryHours), maxUses: number(maxUses), approvalRequired: String(approvalRequired) === 'true' ? 'Y' : 'N'}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {chatInviteLinkId: out.chatInviteLinkId, path: out.path})

const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.revoke#InviteLink').parameter('chatInviteLinkId', chatInviteLinkId || '').call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null}
        : {revoked: !!out.revoked, messageInfos: [{type: 'success', message: ec.l10n.localize('The link is revoked')}]})

const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.get#InviteQr').parameters({chatInviteLinkId: chatInviteLinkId || '',
    baseUrl: ec.web.getWebappRootUrl(true, null) || ''}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {url: out.url || null, qrSvg: out.qrSvg || null})

const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.get#JoinRequestCount').parameter('chatRoomId', chatRoomId || '').call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse({pendingCount: Number(out.pendingCount || 0)})

const ids = chatJoinRequestIds ? String(chatJoinRequestIds).split(',').map((id) => id.trim()).filter((id) => id) : []
const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.decide#JoinRequest').parameters(ids.length ? {chatJoinRequestIdList: ids, decision: decision || ''}
    : {chatJoinRequestId: chatJoinRequestId || '', decision: decision || ''}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null}
        : {decided: !!out.decided, decidedCount: out.decidedCount ?? null, failedList: out.failedList || []})

const out = ec.service.sync().name('org.moqui.chat.ChatInviteServices.request#Join').parameters({chatRoomId: chatRoomId || '', note: note || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null}
        : {outcome: out.outcome || null, chatJoinRequestId: out.chatJoinRequestId || null,
            messageInfos: [{type: 'success', message: ec.l10n.localize('Your request went to the room\'s moderators')}]})
